def clean_abs(path):
    return os.path.normpath(os.path.abspath(path))


def first_missing(path):
    path = clean_abs(path)
    if os.path.exists(path):
        return None
    drive, rest = os.path.splitdrive(path)
    sep = os.path.sep
    if path.startswith(sep):
        cur = drive + sep
        parts = [p for p in path[len(drive + sep):].split(sep) if p]
    else:
        cur = drive or "."
        parts = [p for p in path.split(sep) if p]
    for part in parts:
        if cur in ("", sep, drive + sep):
            candidate = os.path.join(cur, part) if cur else part
        else:
            candidate = os.path.join(cur, part)
        if not os.path.exists(candidate):
            return os.path.normpath(candidate)
