        if a == "--no-input":
            no_input = True
            i += 1
            continue
        if a.startswith("--no-input="):
            val = a.split("=", 1)[1]
            if val.lower() not in VALID_BOOL:
                return None, no_input, help_flag, version, f'--no-input: bool value must be true, 1, yes, false, 0 or no but got "{{val}}"'
            no_input = True
