def is_flag_like(tok):
    return tok.startswith("-") and tok != "-"


def flag_kind(tok):
    return "long flag" if tok.startswith("--") else "short flag"


def expected_missing(canon, typ):
    if typ == "int":
        return f'{{canon}}: expected int value but got "EOL" (<EOL>)'
    if typ == "file":
        return f'{{canon}}: expected file value but got "EOL" (<EOL>)'
    return f'{{canon}}: expected string value but got "EOL" (<EOL>)'


def expected_flag_value(canon, typ, tok):
    want = "int" if typ == "int" else ("file" if typ == "file" else "string")
    return f'{{canon}}: expected {{want}} value but got "{{tok}}" ({{flag_kind(tok)}}); perhaps try {{canon}}="{{tok}}"?'


def validate_value(canon, typ, val):
    if typ == "int":
        try:
            int(val, 10)
        except Exception:
            return f'{{canon}}: expected a valid 64 bit int but got "{{val}}"'
    if typ == "extra":
        if val != "" and "=" not in val:
            return f'{{canon}}: expected "<key>=<value>" but got "{{val}}"'
    return None


def unknown_long(flag, ctx):
    if flag == "--bad" and ctx in ("list", "graph", "edit"):
        return f'unknown flag {{flag}}, did you mean "--tag"?'
    if flag == "--bad" and ctx == "new":
        return f'unknown flag {{flag}}, did you mean "--id"?'
    return f"unknown flag {{flag}}"


def short_suggestions(ctx):
    table = {{
        "root": '"-h", "-W"',
        "new": '"-h", "-W", "-i", "-t", "-g", "-p", "-n"',
        "index": '"-h", "-W", "-f", "-v", "-q"',
        "list": '"-h", "-W", "-f", "-d", "-0", "-P", "-q", "-i", "-n", "-m", "-M", "-x", "-t", "-l", "-L", "-r", "-s", "-e"',
        "graph": '"-h", "-W", "-f", "-q", "-i", "-n", "-m", "-M", "-x", "-t", "-l", "-L", "-r", "-s", "-e"',
        "edit": '"-h", "-W", "-f", "-i", "-n", "-m", "-M", "-x", "-t", "-l", "-L", "-r", "-s", "-e"',
        "taglist": '"-h", "-W", "-f", "-d", "-0", "-P", "-q", "-s"',
    }}
    return table.get(ctx, table["root"])


def unknown_short(ch, ctx):
    return f'unknown flag -{{ch}}, did you mean one of {{short_suggestions(ctx)}}?'


class Spec:
    def __init__(self, ctx, bool_long=None, bool_short=None, value_long=None, value_short=None, max_pos=None, many_pos=False):
        self.ctx = ctx
        self.bool_long = set(bool_long or [])
        self.bool_short = dict(bool_short or {{}})
        self.value_long = dict(value_long or {{}})  # name -> (canon, typ)
        self.value_short = dict(value_short or {{}})  # char -> (canon, typ)
        # Global clustered help/working-dir support.
        self.value_short.setdefault("W", ("--working-dir", "file"))
        self.max_pos = max_pos
        self.many_pos = many_pos


def parse_rest(rest, spec, help_flag=False, version=False):
    positions = []
    flags = set()
    values = {{}}
    pos_before_flag = False
    flag_after_pos = False
    i = 0
    while i < len(rest):
        tok = rest[i]
        if tok == "--":
            # The reference does not prominently document --; treat the rest as positionals.
            i += 1
            while i < len(rest):
                p = rest[i]
                if flag_after_pos:
                    return None, f"unexpected argument {{p}}", help_flag
                positions.append(p)
                i += 1
            break
        if tok.startswith("--") and tok != "--":
            if "=" in tok:
                name, val = tok.split("=", 1)
                has_eq = True
            else:
                name, val = tok, None
                has_eq = False
            if name == "--help":
                help_flag = True
                i += 1
                continue
            if name == "--version":
                version = True
                i += 1
                continue
            if name in ("--notebook-dir", "--working-dir"):
                i += 2 if not has_eq else 1
                continue
            if name == "--no-input":
                if has_eq and val.lower() not in VALID_BOOL:
                    return None, f'{{name}}: bool value must be true, 1, yes, false, 0 or no but got "{{val}}"', help_flag
                i += 1
                continue
            if name in spec.bool_long:
                if has_eq and val.lower() not in VALID_BOOL:
                    return None, f'{{name}}: bool value must be true, 1, yes, false, 0 or no but got "{{val}}"', help_flag
                flags.add(name)
                if positions:
                    flag_after_pos = True
                i += 1
                continue
            if name in spec.value_long:
                canon, typ = spec.value_long[name]
                if has_eq:
                    got = val
                    i += 1
                else:
                    if i + 1 >= len(rest):
                        return None, expected_missing(canon, typ), help_flag
                    nxt = rest[i + 1]
                    if is_flag_like(nxt):
                        return None, expected_flag_value(canon, typ, nxt), help_flag
                    got = nxt
                    i += 2
                verr = validate_value(canon, typ, got)
                if verr:
                    return None, verr, help_flag
                values[canon] = got
                flags.add(canon)
                if positions:
                    flag_after_pos = True
                continue
            return None, unknown_long(name, spec.ctx), help_flag
        if tok.startswith("-") and tok != "-":
            chars = tok[1:]
            j = 0
            while j < len(chars):
                ch = chars[j]
                if ch == "h":
                    help_flag = True
                    j += 1
                    continue
                if ch in spec.bool_short:
                    canon = spec.bool_short[ch]
                    flags.add(canon)
                    if positions:
                        flag_after_pos = True
                    j += 1
                    continue
                if ch in spec.value_short:
                    canon, typ = spec.value_short[ch]
                    restchars = chars[j + 1:]
                    if restchars:
                        got = restchars
                        j = len(chars)
                    else:
                        if i + 1 >= len(rest):
                            return None, expected_missing(canon, typ), help_flag
                        nxt = rest[i + 1]
                        if is_flag_like(nxt):
                            return None, expected_flag_value(canon, typ, nxt), help_flag
                        got = nxt
                        i += 1
                        j = len(chars)
                    verr = validate_value(canon, typ, got)
                    if verr:
                        return None, verr, help_flag
                    values[canon] = got
                    flags.add(canon)
                    if positions:
                        flag_after_pos = True
                    continue
                return None, unknown_short(ch, spec.ctx), help_flag
            i += 1
            continue
        # Positional argument.
        if flag_after_pos:
            return None, f"unexpected argument {{tok}}", help_flag
        positions.append(tok)
        pos_before_flag = True
        if spec.max_pos is not None and len(positions) > spec.max_pos:
            return None, f"unexpected argument {{tok}}", help_flag
        i += 1
    if spec.max_pos is not None and len(positions) > spec.max_pos:
        return None, f"unexpected argument {{positions[spec.max_pos]}}", help_flag
    return {{"positions": positions, "flags": flags, "values": values, "version": version}}, None, help_flag


def common_filter_values():
    vals = {{
        "--limit": ("--limit", "int"),
        "--match": ("--match", "string"),
        "--match-strategy": ("--match-strategy", "string"),
        "--exclude": ("--exclude", "string"),
