def make_spec(cmd):
    if cmd == "root":
        return Spec("root", max_pos=0)
    if cmd == "init":
        return Spec("init", max_pos=1)
    if cmd == "index":
        return Spec("index", bool_long={"--force", "--verbose", "--quiet"}, bool_short={"f": "--force", "v": "--verbose", "q": "--quiet"}, max_pos=0)
    if cmd == "new":
        return Spec(
            "new",
            bool_long={"--interactive", "--print-path", "--dry-run"},
            bool_short={"i": "--interactive", "p": "--print-path", "n": "--dry-run"},
            value_long={
                "--title": ("--title", "string"),
                "--date": ("--date", "string"),
                "--group": ("--group", "string"),
                "--extra": ("--extra", "extra"),
                "--template": ("--template", "string"),
                "--id": ("--id", "string"),
            },
            value_short={"t": ("--title", "string"), "g": ("--group", "string")},
            max_pos=1,
        )
    if cmd in ("list", "graph", "edit"):
        vals = common_filter_values()
        shorts = common_filter_shorts()
        bools = {"--interactive", "--orphan", "--tagless", "--missing-backlink", "--recursive"}
        bshort = {"i": "--interactive", "r": "--recursive"}
        if cmd == "list":
            vals.update({
                "--format": ("--format", "string"),
                "--header": ("--header", "string"),
                "--footer": ("--footer", "string"),
                "--delimiter": ("--delimiter", "string"),
            })
            shorts.update({"f": ("--format", "string"), "d": ("--delimiter", "string")})
            bools.update({"--delimiter0", "--no-pager", "--quiet"})
            bshort.update({"0": "--delimiter0", "P": "--no-pager", "q": "--quiet"})
        elif cmd == "graph":
            vals.update({"--format": ("--format", "string")})
            shorts.update({"f": ("--format", "string")})
            bools.update({"--quiet"})
            bshort.update({"q": "--quiet"})
        elif cmd == "edit":
            bools.update({"--force"})
            bshort.update({"f": "--force"})
        return Spec(cmd, bool_long=bools, bool_short=bshort, value_long=vals, value_short=shorts, many_pos=True)
    if cmd == "taglist":
        return Spec(
            "taglist",
            bool_long={"--delimiter0", "--no-pager", "--quiet"},
            bool_short={"0": "--delimiter0", "P": "--no-pager", "q": "--quiet"},
            value_long={
                "--format": ("--format", "string"),
                "--header": ("--header", "string"),
                "--footer": ("--footer", "string"),
                "--delimiter": ("--delimiter", "string"),
                "--sort": ("--sort", "string"),
            },
            value_short={"f": ("--format", "string"), "d": ("--delimiter", "string"), "s": ("--sort", "string")},
            max_pos=0,
        )
    return Spec(cmd)


def no_notebook(start):
    return error(f"failed to open notebook: no notebook found in {start} or a parent directory")


def fts_fail():
    return error(FTS_ERROR)


def do_init(parsed, no_input):
    positions = parsed["positions"]
    target = positions[0] if positions else "."
    if not no_input:
        prompt = "\x1b[0G\x1b[2K\x1b[0;1;92m? \x1b[0m\x1b[0;1;99mDo you prefer [[WikiLinks]] over regular Markdown links? \x1b[0m\x1b[0;37m(y/N) \x1b[0m\x1b[?25l\x1b7\x1b[999;999f\x1b[6n\x1b8\x1b[?25h\x1b[6n"
        out(prompt)
        sys.stdout.flush()
        return error("EOF")
    out("\n")
    sys.stdout.flush()
    abs_target = clean_abs(target)
    if os.path.exists(abs_target) and not os.path.isdir(abs_target):
        return error(f"init: mkdir {abs_target}: not a directory")
    try:
        os.makedirs(os.path.join(abs_target, ".zk", "templates"), exist_ok=True)
        with open(os.path.join(abs_target, ".zk", "config.toml"), "w", encoding="utf-8") as f:
            f.write(DEFAULT_CONFIG)
        with open(os.path.join(abs_target, ".zk", "templates", "default.md"), "w", encoding="utf-8") as f:
            f.write(DEFAULT_TEMPLATE)
        open(os.path.join(abs_target, ".zk", "notebook.db"), "a").close()
    except OSError as exc:
        return error(f"init: {exc}")
    return fts_fail()


def handle_command(cmd, rest, no_input, help_flag, version, start):
    if cmd == "tag":
        if rest and rest[0] == "list":
            parsed, perr, help_flag = parse_rest(rest[1:], make_spec("taglist"), help_flag, version)
            if perr:
                return error(perr)
            if version or parsed.get("version"):
                out(VERSION)
                return 0
            if help_flag:
                out(HELP["taglist"])
                return 0
            return no_notebook(start)
        if rest and not rest[0].startswith("-"):
            return error(f"unexpected argument {rest[0]}")
        parsed, perr, help_flag = parse_rest(rest, Spec("tag", max_pos=0), help_flag, version)
        if perr:
            return error(perr)
        if version or parsed.get("version"):
            out(VERSION)
            return 0
        if help_flag:
            out(HELP["tag"])
            return 0
        return no_notebook(start)

    parsed, perr, help_flag = parse_rest(rest, make_spec(cmd), help_flag, version)
    if perr:
        return error(perr)
    if version or parsed.get("version"):
        out(VERSION)
        return 0
    if help_flag:
        out(HELP[cmd])
        return 0

    if cmd == "index":
        if "--verbose" in parsed["flags"] and "--quiet" in parsed["flags"]:
            return error("--verbose and --quiet can't be used together")
    if cmd == "graph":
        if "--format" not in parsed["flags"]:
            return error("missing flags: --format=STRING")
        if parsed["values"].get("--format") != "json":
            return error(f'--format must be one of "json" but got "{parsed["values"].get("--format", "")}"')
    if cmd == "init":
        return do_init(parsed, no_input)
    return no_notebook(start)


def main(argv):
    start, notebook, pre_err = parse_prescan(argv)
    if pre_err is not None:
        return pre_err
    if notebook is not None:
        return fts_fail()

    stripped, no_input, help_flag, version, serr = strip_globals(argv)
    if serr:
        return error(serr)

    if not stripped:
        if version:
            out(VERSION)
        else:
            out(HELP["root"])
        return 0

    first = stripped[0]
    if first.startswith("-"):
        parsed, perr, help_flag = parse_rest(stripped, make_spec("root"), help_flag, version)
        if perr:
            return error(perr)
        if version or parsed.get("version"):
            out(VERSION)
            return 0
        out(HELP["root"])
        return 0

    if first not in ROOT_COMMANDS:
        return error(f"unexpected argument {first}")

    return handle_command(first, stripped[1:], no_input, help_flag, version, start)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
